"""Shared utilities for the hadronic top reconstruction pipeline."""
import json
import os

import numpy as np

RESULTS = "/root/results"
DATA = "/root/data/ttbar.root"
TREE = "output"

M_TOP = 172.5
M_W = 80.379


def ensure(*paths):
    for p in paths:
        os.makedirs(p, exist_ok=True)
    return paths[0] if len(paths) == 1 else paths


def write_json(path, obj):
    ensure(os.path.dirname(path))
    with open(path, "w") as fh:
        json.dump(obj, fh, indent=2, default=_default)
    return path


def _default(o):
    if isinstance(o, (np.integer,)):
        return int(o)
    if isinstance(o, (np.floating,)):
        return float(o)
    if isinstance(o, (np.ndarray,)):
        return o.tolist()
    if isinstance(o, (np.bool_,)):
        return bool(o)
    raise TypeError(type(o))


def delta_phi(a, b):
    d = a - b
    return (d + np.pi) % (2.0 * np.pi) - np.pi


def delta_r(eta1, phi1, eta2, phi2):
    return np.hypot(eta1 - eta2, delta_phi(phi1, phi2))


def ptetaphim_to_p4(pt, eta, phi, m):
    """Return (px, py, pz, E) from massive (pt, eta, phi, m)."""
    px = pt * np.cos(phi)
    py = pt * np.sin(phi)
    pz = pt * np.sinh(eta)
    e = np.sqrt(np.maximum(px * px + py * py + pz * pz + m * m, 0.0))
    return px, py, pz, e


def p4_to_ptetaphim(px, py, pz, e):
    pt = np.hypot(px, py)
    p = np.sqrt(px * px + py * py + pz * pz)
    with np.errstate(divide="ignore", invalid="ignore"):
        eta = np.arctanh(np.clip(np.divide(pz, p, out=np.zeros_like(pz), where=p > 0), -1 + 1e-12, 1 - 1e-12))
    phi = np.arctan2(py, px)
    m2 = e * e - p * p
    m = np.sqrt(np.maximum(m2, 0.0))
    return pt, eta, phi, m


def roc_auc(y_true, score):
    """AUC via the rank / Mann-Whitney U identity (ties handled with mid-ranks)."""
    y = np.asarray(y_true).astype(np.int8)
    s = np.asarray(score, dtype=np.float64)
    n1 = int((y == 1).sum())
    n0 = int((y == 0).sum())
    if n1 == 0 or n0 == 0:
        return float("nan")
    order = np.argsort(s, kind="mergesort")
    s_sorted = s[order]
    ranks = np.empty(len(s), dtype=np.float64)
    i = 0
    while i < len(s):
        j = i
        while j + 1 < len(s) and s_sorted[j + 1] == s_sorted[i]:
            j += 1
        ranks[order[i:j + 1]] = 0.5 * (i + j) + 1.0
        i = j + 1
    return float((ranks[y == 1].sum() - n1 * (n1 + 1) / 2.0) / (n1 * n0))


def average_precision(y_true, score):
    y = np.asarray(y_true).astype(np.int8)
    s = np.asarray(score, dtype=np.float64)
    if y.sum() == 0:
        return float("nan")
    order = np.argsort(-s, kind="mergesort")
    y = y[order]
    tp = np.cumsum(y)
    prec = tp / np.arange(1, len(y) + 1)
    return float((prec * y).sum() / y.sum())


def binary_metrics(y_true, score, thr=0.5):
    y = np.asarray(y_true).astype(np.int8)
    p = (np.asarray(score) >= thr).astype(np.int8)
    tp = int(((y == 1) & (p == 1)).sum())
    fp = int(((y == 0) & (p == 1)).sum())
    fn = int(((y == 1) & (p == 0)).sum())
    tn = int(((y == 0) & (p == 0)).sum())
    prec = tp / (tp + fp) if tp + fp else 0.0
    rec = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * prec * rec / (prec + rec) if prec + rec else 0.0
    return {
        "threshold": thr, "tp": tp, "fp": fp, "fn": fn, "tn": tn,
        "accuracy": (tp + tn) / max(len(y), 1),
        "precision": prec, "recall": rec, "f1": f1,
    }

